-- Identity: users, sign-in methods and opaque sessions (ARCHITECTURE §5.1, §15, ADR-0016, T0.3.1).
-- Owned by the `identity` crate; other crates never read these tables with SQL (ADR-0007).
--
-- Ids are UUIDv7 generated by the application (kernel::Id); the CHECKs reject any other version
-- (uuid_extract_version is NULL for non-RFC 9562 variants, hence IS NOT DISTINCT FROM).
-- All timestamps are timestamptz (UTC).

CREATE TABLE users (
    id                    uuid        PRIMARY KEY CHECK (uuid_extract_version(id) IS NOT DISTINCT FROM 7),
    email                 text        NOT NULL CHECK (email <> '' AND email = btrim(email)),
    display_name          text        NOT NULL CHECK (btrim(display_name) <> ''),
    avatar_url            text,
    timezone              text        NOT NULL DEFAULT 'UTC',  -- IANA name, validated by the app
    locale                text        NOT NULL DEFAULT 'tr',   -- BCP 47 tag
    created_at            timestamptz NOT NULL DEFAULT now(),
    deletion_requested_at timestamptz                          -- HS2: account deletion grace period
);

-- One account per address, regardless of letter case.
CREATE UNIQUE INDEX users_email_lower_key ON users (lower(email));

-- How a user signs in. A user may have several methods but at most one per provider.
--   password: provider_uid is the user's id (text), password_hash is the argon2id PHC string.
--   google / apple: provider_uid is the provider's stable subject id, password_hash is NULL.
CREATE TABLE auth_identities (
    user_id       uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    provider      text        NOT NULL CHECK (provider IN ('password', 'google', 'apple')),
    provider_uid  text        NOT NULL CHECK (provider_uid <> ''),
    password_hash text,
    created_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (provider, provider_uid),
    UNIQUE (user_id, provider),
    CONSTRAINT auth_identities_password_hash_check CHECK (
        (provider = 'password') = (password_hash IS NOT NULL)
    )
);

-- Opaque session tokens (§15): the client holds a 256-bit random token; only its SHA-256 digest
-- is stored, so a database leak does not expose usable tokens.
CREATE TABLE sessions (
    id           uuid        PRIMARY KEY CHECK (uuid_extract_version(id) IS NOT DISTINCT FROM 7),
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash   bytea       NOT NULL CHECK (octet_length(token_hash) = 32),
    device       text,                                  -- client label, e.g. "iOS · iPhone"
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    CONSTRAINT sessions_token_hash_key UNIQUE (token_hash),
    CONSTRAINT sessions_expiry_check CHECK (expires_at > created_at)
);

-- "Sign out of all devices" and the device list look sessions up by user.
CREATE INDEX sessions_user_id_idx ON sessions (user_id);
-- Periodic cleanup of expired sessions.
CREATE INDEX sessions_expires_at_idx ON sessions (expires_at);
